-- GenDB engine variant Q13-always_true_conjunct: template q13.sql, kind always_true_conjunct (generated by generate.py; frozen)
SELECT
  c_count,
  COUNT(*) AS custdist
FROM (
  SELECT
    c_custkey,
    COUNT(o_orderkey) AS c_count
  FROM customer
  LEFT OUTER JOIN orders
    ON c_custkey = o_custkey AND NOT o_comment LIKE $1
  WHERE
    c_custkey = c_custkey
  GROUP BY
    c_custkey
) AS c_orders
GROUP BY
  c_count
ORDER BY
  custdist DESC,
  c_count DESC
